/* Container: centred column with side padding. */
.container { width: 100%; margin-inline: auto; padding-inline: var(--s5); }
.container-text { max-width: calc(var(--measure) + 2 * var(--s5)); }
.container-page { max-width: calc(var(--content) + 2 * var(--s5)); }
.container-full { max-width: none; }

.heading { font-weight: 500; line-height: 1.15; text-wrap: balance; }
.heading-display { font-family: var(--font-display); font-weight: 700; font-size: var(--display-md); letter-spacing: -0.035em; line-height: 0.95; }
.heading-xl { font-family: var(--font-display); font-weight: 700; font-size: var(--display-sm); letter-spacing: -0.03em; }
.heading-lg { font-size: calc(var(--text-lg) * 1.35); }
.heading-md { font-size: var(--text-lg); }
.heading-sm { font-size: var(--text-base); }

.text { max-width: var(--measure); }
.text-xs { font-size: var(--text-xs); } .text-sm { font-size: var(--text-sm); } .text-md { font-size: var(--text-base); } .text-lg { font-size: var(--text-lg); }
.text-muted { color: var(--muted); } .text-danger { color: var(--danger); } .text-ok { color: var(--ok); } .text-accent { color: var(--accent-text); }
.text-truncate { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }

/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 14px 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { padding-left: 0; padding-right: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { padding: 6px 12px; font-size: var(--text-xs); }
.btn-block { width: 100%; }

/* Block: call to action. */
.block-cta { padding-block: var(--s8); }
.block-cta-box { display: flex; flex-direction: column; gap: var(--s5); padding: var(--s6); border: 1px solid var(--foreground); }
.block-cta-copy { display: flex; flex-direction: column; gap: var(--s2); max-width: var(--measure); }
.block-cta-actions { display: flex; flex-wrap: wrap; gap: var(--s3); }
@media (min-width: 760px) {
  .block-cta-box { flex-direction: row; align-items: center; justify-content: space-between; }
  .block-cta-actions { flex-shrink: 0; }
}

